import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"18、【蛊】 巽下艮上","description":"周易集注 - 18、【蛊】 巽下艮上","frontmatter":{"title":"18、【蛊】 巽下艮上","description":"周易集注 - 18、【蛊】 巽下艮上"},"headers":[],"relativePath":"zh/classics/jizhu/022.md","filePath":"zh/classics/jizhu/022.md"}'),h={name:"zh/classics/jizhu/022.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_18、【蛊】-巽下艮上" tabindex="-1">18、【蛊】 巽下艮上 <a class="header-anchor" href="#_18、【蛊】-巽下艮上" aria-label="Permalink to “18、【蛊】 巽下艮上”">​</a></h1><p>蛊者，物久败坏而蛊生也。以卦德论，在上者止息而不动作，在下者巽顺而无违忤，彼此委靡因循，此其所以蛊也。《序卦》“以喜随人者必有事，故受之以蛊”，所以次随。</p><p>利涉大川者，中爻震木，在兑泽之上也。先甲后甲者，本卦艮上巽下，文王圆图艮巽夹震木于东之中，故曰先甲后甲，言巽先于甲，艮后于甲也。巽卦言先庚后庚者，伏羲圆图艮巽夹兑方于西之中，故曰先庚后庚，言巽先于庚，艮后于庚也。分甲于蛊者，本卦未变，上体中爻震木，下体巽木也。分庚于巽者，本卦未变，上体综兑金，下体综兑金也。十干独言甲庚者，乾坤乃六十四卦之祖，甲居于寅，坤在上干在下为泰，庚居于申，干在上坤在下为否，大往小来，小往大来，天地之道，不过如此。物不可以终通，物不可以终否，易之为道，亦不过如此，所以独言甲庚也。曰先三后三者六爻也，先三者下三爻也，巽也，后三者上三爻也艮也。不曰爻而曰日者，本卦综随，日出震东，日没兑西，原有此象，故少不言一日二日，多不言九日十日，而独言先三后三者，则知其为下三爻上三爻也明矣。以先甲用辛，取自新，后甲用丁，取丁宁，此说始于郑玄，不成其说矣。</p><p>当蛊之时，乱极必治，占者固元亨矣。然岂静以俟其治哉?必历涉艰难险阻，以拨乱反正，知其先之三爻，乃巽之柔懦，所以成其蛊也，则因其柔懦而矫之以刚果，知其后之三爻，乃艮之止息，所以成其蛊也。则因其止息，而矫之以奋发，斯可以元亨而天下治矣。</p><p>《彖》曰：蛊刚上而柔下，巽而止，蛊。蛊，元亨而天下治也，利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。</p><p>以卦综卦德释卦名卦辞。刚上而柔下者，蛊综随，随初震之刚上而为艮，上六兑之柔下而为巽也。刚上则太尊而情不下达，柔下则太卑而情难上通。巽则謟，止则惰，皆致蛊之由，所以名蛊。既蛊矣，而又元亨，何也?盖造化之与人事，穷则变矣。治必因乱，乱则将治，故蛊而乱之终，乃治之始也。如五胡之后生唐太宗，五季之末生宋太祖是也。治蛊者，当斯时则天下治矣，故占者元亨。往有事，犹言往有为。方天下坏乱，当勇往以济难，若复巽懦止息，则终于蛊矣，岂能元亨。终始即先后，成言乎艮者终也，齐乎巽者始也，终则有始者，如昼之终矣，而又有夜之始，夜之终矣，而又有昼之始。故乱不终乱，乱之终乃其治之始，治乱相仍，乃天运之自然也。故治蛊者，必原其始，必推其终，知其蛊之为始为先者乃巽也，则矫之以刚。果知其蛊之为终为后者乃艮也，则矫之以奋发，则蛊治而元亨矣。恒卦上体震综艮，下体巽，故亦曰终则有始。</p><h3 id="《象》曰-山下有风-蛊-君子以振民育德。" tabindex="-1">《象》曰：山下有风，蛊，君子以振民育德。 <a class="header-anchor" href="#《象》曰-山下有风-蛊-君子以振民育德。" aria-label="Permalink to “《象》曰：山下有风，蛊，君子以振民育德。”">​</a></h3><p>山下有风，则物坏而有事更新矣。振民者，鼓舞作兴，以振起之，使之日趋于善，非巽之柔弱也，此新民之事也。育德者，操存省察，以涵育之，非艮之止息也，此明德之事也。当蛊之事，风俗颓败，由于民德之不新。民德不新，由于己德之不明。故救时之急，在于振民。振民又在于育德，盖相因之辞也。</p><p>初六，干父之蛊，有子考，无咎，厉终吉。</p><p>艮止于上，犹父道之无为而尊于上也。巽顺于下，犹子道之服劳而顺于下也。故蛊多言干父之事，干者，木之茎干也。中爻震木，下体巽木，干之象也。木有干，方能附其繁茂之枝叶。人有才，能方能振作其既堕之家声，故曰干蛊。有子者，即《礼记》之幸哉有子也。</p><p>初六当蛊之时，才柔志刚，故有能干父蛊之象。占者如是，则能克盖前愆。喜其今日之维新，忘其前日之废堕，因子而考亦可以无咎矣。但谓之蛊未免危厉，知其危厉，不以易心处之，则终得吉矣。因六柔，故又戒之以此。</p><h3 id="《象》曰-干父之蛊-意承考也。" tabindex="-1">《象》曰：干父之蛊，意承考也。 <a class="header-anchor" href="#《象》曰-干父之蛊-意承考也。" aria-label="Permalink to “《象》曰：干父之蛊，意承考也。”">​</a></h3><p>意承考者，心之志意，在于承当父事，克盖前愆，所以考无咎。</p><p>九二，干母之蛊，不可贞。</p><p>艮性止，止而又柔，止则惰，柔则暗，又当家事败坏之时，子欲干其蛊。若以我阳刚中直之性，直遂干之，则不惟不堪，亦且难入，即伤恩矣，其害不小。惟当屈己下意，巽顺将承，使之身正事治，则亦已矣，故曰不可贞，事父母几谏是也。若以君臣论，周公之事成王，成王有过，则橽伯禽，皆此意也。易之时正在于此。</p><p>九二当蛊之时，上应六五，六五阴柔，故有干母蛊之象。然九二刚中，以刚承柔，恶其过于直遂也，故戒占者不可贞，委曲巽顺以干之可也。</p><h3 id="《象》曰-干母之蛊-得中道也。" tabindex="-1">《象》曰：干母之蛊，得中道也。 <a class="header-anchor" href="#《象》曰-干母之蛊-得中道也。" aria-label="Permalink to “《象》曰：干母之蛊，得中道也。”">​</a></h3><p>得中道而不太过，即不可贞也。</p><p>九三，干父之蛊，小有悔，无大咎。</p><p>悔以心言。悔者因九三过刚，则干蛊之事，更张措置之间，未免先后缓急失其次序，所以悔也。咎以理言，然巽体得正，能制其刚，则其干蛊，必非私意妄行矣，所以无大咎。</p><p>九三以阳刚之才，能干父之蛊者，故有干蛊之象。然过刚自用，其心不免小有悔，但为父干蛊，其咎亦不大矣，故其占如此。</p><h3 id="《象》曰-干父之蛊-终无咎也。" tabindex="-1">《象》曰：干父之蛊，终无咎也。 <a class="header-anchor" href="#《象》曰-干父之蛊-终无咎也。" aria-label="Permalink to “《象》曰：干父之蛊，终无咎也。”">​</a></h3><p>有阳刚之才，方能干蛊，故周公仅许之，而孔子深许之也。</p><p>六四，裕父之蛊，往见吝。</p><p>裕，宽裕也，强以立事为干，怠而委事为裕，正干之反也。往者以此而往治其蛊也，见吝者，立见其羞吝也。治蛊如拯溺救焚，犹恐缓不及事，岂可裕。</p><p>六四以阴居阴，又当艮止，柔而且怠，不能有为，故有裕蛊之象，如是则蛊将日深，故往则见吝，戒占者不可如是也。</p><h3 id="《象》曰-裕父之蛊-往未得也。" tabindex="-1">《象》曰：裕父之蛊，往未得也。 <a class="header-anchor" href="#《象》曰-裕父之蛊-往未得也。" aria-label="Permalink to “《象》曰：裕父之蛊，往未得也。”">​</a></h3><p>未得者，未得治其蛊也。九三之刚，失之过，故悔，悔者渐趋于吉，故终无咎。六四之柔，失之不及，故吝，吝者渐趋于凶，故往未得，宁为悔，不可为吝。</p><p>六五，干父之蛊，用誉。</p><p>用者用人也，用誉者因用人而得誉也。二多誉，誉之象也。周公曰用誉，孔子二多誉之言，盖本于此。九二以五为母，六五又取子道，可见易不可为典要。宋仁宗柔之主，得韩范富欧卒为宋令主，此爻近之。</p><p>六五以柔居尊，下应九二，二以刚中之才而居巽体，则所以承顺乎五者，莫非刚健大中之德矣。以此治蛊，可得闻誉，然非自能誉也，用人而得其誉也。故其象占如此。</p><h3 id="《象》曰-干父用誉-承以德也。" tabindex="-1">《象》曰：干父用誉，承以德也。 <a class="header-anchor" href="#《象》曰-干父用誉-承以德也。" aria-label="Permalink to “《象》曰：干父用誉，承以德也。”">​</a></h3><p>承者承顺也，因巽体又居下，故曰承，言九二承顺以刚中之德也。</p><p>上九，不事王侯，高尚其事。</p><p>上事字，事王侯以治蛊也，下事字，以高尚为事也。耕于有莘之野，而乐尧舜之道是也。上与五二爻以家事言，则上为父，五为母，众爻为子。观诸爻以干父母言，可知矣。以国事言，则五为君，下四爻为用事之臣，上一爻为不事之臣，观上一爻，以王侯言，可知矣，此易所以不可为典要也。盖当蛊之世，任其事而干蛊者，则操巽命之权，而行其所当行，不任其事而高尚者，则体艮止之义，而止其所当止，如邓禹诸臣，皆相光武以干汉室之蛊，独子陵钓于富春是也，艮止不事之象。变坤错干，王侯之象。巽为高，高尚之象。</p><p>初至五皆干蛊，上有用誉之君，下有刚中之臣，家国天下之事已毕矣。上九居蛊之终，无系应于下，在事之外，以刚明之才，无应援而处无事之地，盖贤人君子，不偶于时，而高洁自守者也，故有此象。占者有是德，斯应是占矣。</p><h3 id="《象》曰-不事王侯-志可则也。" tabindex="-1">《象》曰：不事王侯，志可则也。 <a class="header-anchor" href="#《象》曰-不事王侯-志可则也。" aria-label="Permalink to “《象》曰：不事王侯，志可则也。”">​</a></h3><p>高尚之志，足以起顽立懦，故可则。</p>',38)])])}const m=e(h,[["render",t]]);export{_ as __pageData,m as default};
